# -*- coding: utf-8 -*-
"""Emit MK Drywall site files as UTF-8 without BOM."""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent


def write_utf8_no_bom(rel_path: str, text: str) -> None:
    path = ROOT / rel_path
    path.write_bytes(text.encode("utf-8"))



