def polish_index(html: str) -> str:
    for old, new in POLISH_INDEX:
        html = html.replace(old, new)
    return html


def polish_js(js: str) -> str:
    for old, new in POLISH_JS:
        js = js.replace(old, new)
    return js

def read_style_css() -> str:
    path = ROOT / "style.css"
    raw = path.read_bytes()
    if raw.startswith(b"\xef\xbb\xbf"):
        raw = raw[3:]
    for enc in ("utf-8", "cp1252", "latin-1"):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    else:
        text = raw.decode("utf-8", errors="replace")
    header = (
        "/* ==========================================================================\n"
        "   MK Drywall Solu\u00e7\u00f5es \u2014 Design System\n"
        "   ========================================================================== */\n\n"
    )
    root_idx = text.find(":root {")
    body = text[root_idx:] if root_idx >= 0 else text
    return header + body

